        .padEnd(Math.ceil(b64url.length / 4) * 4, "=");

      const bin = atob(b64);
      const out = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
      return out;
    }

    function bytesToStr(bytes) {
      return new TextDecoder().decode(bytes);
    }

    async function getAesKey() {
      const hash = await crypto.subtle.digest(
        "SHA-256",
        new TextEncoder().encode(SECRET)
      );
      return crypto.subtle.importKey(
        "raw",
        hash,
        { name: "AES-GCM" },
        false,
        ["decrypt"]
      );
    }

    async function decryptToken(token) {
      const bytes = base64urlToBytes(token);
      if (bytes.length < 13) throw new Error("Token too short");

      const iv = bytes.slice(0, 12);
      const cipher = bytes.slice(12);

      const key = await getAesKey();
      const plainBuf = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, cipher);
      const plainStr = bytesToStr(new Uint8Array(plainBuf));
      return JSON.parse(plainStr);
    }

    function formatScore(score) {
      const d = Number(score?.d ?? 0);
      const i = Number(score?.i ?? 0);
      const s = Number(score?.s ?? 0);
      const c = Number(score?.c ?? 0);
      return `D:${d}, I:${i}, S:${s}, C:${c}`;
    }

    async function init() {
      const token = getTokenFromUrl();

      // 1) link field = текущий URL (со строкой токена)
      const linkInput = qs("#discLink");
      if (linkInput) linkInput.value = location.href;

      // 2) score
      const scoreSpan = qs(".result__score span");
      if (!scoreSpan) return;

      if (!token) {
        scoreSpan.textContent = "D:0, I:0, S:0, C:0";
        return;
      }

      try {
        const data = await decryptToken(token);
        const str = formatScore(data?.score);
        scoreSpan.textContent = str;
      } catch (e) {
        // если токен битый/чужой секрет — показываем нейтрально
        scoreSpan.textContent = "D:0, I:0, S:0, C:0";
      }
    }

    // 3) copy button (с UI-статусом)
    function initCopy() {
      const setState = (btn, copied) => {
        const txt = btn.querySelector(".copyfield__btnText");
        if (!txt) return;

        if (!btn.dataset.defaultText) btn.dataset.defaultText = txt.textContent.trim();

        if (copied) {
          txt.textContent = "Скопировано";
          btn.classList.add("is-copied");
        } else {
          txt.textContent = btn.dataset.defaultText;
          btn.classList.remove("is-copied");
        }
      };

      document.addEventListener("click", async (e) => {
        const btn = e.target.closest("[data-copy]");
        if (!btn) return;

        const sel = btn.getAttribute("data-copy");
        const input = sel ? qs(sel) : null;
        if (!input) return;

        if (btn.dataset.copyBusy === "1") return;
        btn.dataset.copyBusy = "1";

        const text = input.value || "";
        let ok = false;

        // modern
        if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
          try {
            await navigator.clipboard.writeText(text);
            ok = true;
          } catch (_) {}
        }

        // fallback
        if (!ok) {
          input.focus();
          input.select();
          input.setSelectionRange(0, text.length);
          try {
            ok = document.execCommand("copy");
          } catch (_) {
            ok = false;
          }
          input.blur();
        }

        if (ok) setState(btn, true);

        window.setTimeout(() => {
          setState(btn, false);
          btn.dataset.copyBusy = "0";
        }, 1500);
      });
    }

    initCopy();
    init();
  })();

